import{_ as o,C as r,o as d,c as i,j as t,a,E as n,a6 as l}from"./chunks/framework.BgIEWZ8W.js";const f=JSON.parse(`{"title":"Websec Decompiled","description":"Detective-style web security training across all 31 PortSwigger Academy topics and 272 labs—explained in plain English.","frontmatter":{"layout":"home","title":"Websec Decompiled","description":"Detective-style web security training across all 31 PortSwigger Academy topics and 272 labs—explained in plain English.","hero":{"name":"Websec Decompiled","text":"Follow the request. Spot where the logic breaks.","tagline":"A guided, plain-English web security learning path covering all 31 PortSwigger Academy topics and 272 labs. Every bug is explained like a detective story—from what you notice in the browser, to what the server actually runs, to how to fix it.","image":{"src":"/hero.svg","alt":"Diagram of an HTTP request traveling from browser to server, highlighting where user input changes the server's behavior"},"actions":[{"theme":"brand","text":"Start Stage 1 · First Steps","link":"/information-disclosure/"},{"theme":"alt","text":"SQLi Deep Track","link":"/sql-injection/"},{"theme":"alt","text":"📖 Jargon Buster","link":"/glossary/"}]},"features":[{"icon":"🕵️","title":"Detective Case-File Flow","details":"Every concept follows four simple steps—🔎 What You See in the Browser, ⚙️ What the Server Does, 💥 Where the Logic Breaks, and 🛡️ How to Fix It."},{"icon":"🗺️","title":"6-Stage Guided Learning Path","details":"No more wondering what to study next. All 35 modules and 272 labs are ordered from beginner recon all the way to advanced protocol internals."},{"icon":"📖","title":"Zero Textbook Jargon","details":"Heavy buzzwords are replaced with everyday analogies, color-coded visual breakdowns, and a built-in Plain-English Jargon Buster on every page."},{"icon":"💡","title":"One-Clue-at-a-Time Hints","details":"Stuck on a lab? Reveal Clue 1 for a gentle mental nudge without spoiling Clue 2 or the full walkthrough underneath."},{"icon":"📝","title":"Bookmarks, Notes & Filters","details":"Filter labs by difficulty, hide solved labs, star tricky topics for review later, and write personal notes—all saved locally with JSON backup."},{"icon":"📡","title":"100% Offline-First","details":"Theory, visual diagrams, hints, solutions, and your personal notes work completely offline. Only launching the live practice labs requires the internet."}]},"headers":[],"relativePath":"index.md","filePath":"index.md"}`),c={name:"index.md"};function h(p,e,g,u,b,m){const s=r("ProgressDashboard");return d(),i("div",null,[e[0]||(e[0]=t("div",{class:"wd-callout"},[t("p",null,[t("strong",null,"Welcome to your investigation desk."),a(" You don't need to memorize magic payloads or read dry compiler textbooks to master web security. Every vulnerability happens because a developer expected one thing and the server did another. Once you can picture that gap, you can spot and fix the bug anywhere.")])],-1)),e[1]||(e[1]=t("h2",{id:"progress",tabindex:"-1"},[a("Your Investigation Dashboard "),t("a",{class:"header-anchor",href:"#progress","aria-label":'Permalink to "Your Investigation Dashboard {#progress}"'},"​")],-1)),n(s),e[2]||(e[2]=l('<h2 id="syllabus" tabindex="-1">The 6-Stage Guided Learning Path <a class="header-anchor" href="#syllabus" aria-label="Permalink to &quot;The 6-Stage Guided Learning Path {#syllabus}&quot;">​</a></h2><p class="wd-section-lede">Instead of dumping 31 topics in a random list, the curriculum is organized into <strong>six logical stages (35 steps total)</strong>. Follow them in order from Step 01 to Step 35, or jump straight to any case file you want to investigate.</p><h3 id="🔎-stage-1-·-first-steps-recon" tabindex="-1">🔎 Stage 1 · First Steps &amp; Recon <a class="header-anchor" href="#🔎-stage-1-·-first-steps-recon" aria-label="Permalink to &quot;🔎 Stage 1 · First Steps &amp; Recon&quot;">​</a></h3><p><em>Start here. Learn how websites accidentally leak backstage blueprints and how servers look up files on disk.</em></p><table tabindex="0"><thead><tr><th>Step</th><th>Case File</th><th>The Investigation Question</th><th>Labs</th></tr></thead><tbody><tr><td><strong>01</strong></td><td><a href="/websec-decompiled/information-disclosure/">Information Disclosure</a></td><td>What backstage clues (error pages, backup files, <code>.git</code> folders) did the developers leave in plain sight?</td><td>5</td></tr><tr><td><strong>02</strong></td><td><a href="/websec-decompiled/path-traversal/">Path Traversal</a></td><td>When a URL asks for <code>filename=shirt.jpg</code>, how can <code>../</code> trick the server into reading private system files?</td><td>6</td></tr><tr><td><strong>03</strong></td><td><a href="/websec-decompiled/essential-skills/">Essential Skills</a></td><td>How do you efficiently pinpoint a bug and read unfamiliar data formats during a test?</td><td>2</td></tr></tbody></table><h3 id="🔐-stage-2-·-logins-accounts-logic" tabindex="-1">🔐 Stage 2 · Logins, Accounts &amp; Logic <a class="header-anchor" href="#🔐-stage-2-·-logins-accounts-logic" aria-label="Permalink to &quot;🔐 Stage 2 · Logins, Accounts &amp; Logic&quot;">​</a></h3><p><em>Once you can read requests, investigate how websites check who you are, what you&#39;re allowed to touch, and whether you followed the rules.</em></p><table tabindex="0"><thead><tr><th>Step</th><th>Case File</th><th>The Investigation Question</th><th>Labs</th></tr></thead><tbody><tr><td><strong>04</strong></td><td><a href="/websec-decompiled/authentication/">Authentication</a></td><td>How do login forms, 2FA screens, and password-reset links accidentally give away valid accounts or let attackers slip past?</td><td>14</td></tr><tr><td><strong>05</strong></td><td><a href="/websec-decompiled/access-control/">Access Control</a></td><td>Once you&#39;re logged in, does the server actually check if you own the account or admin page you just requested?</td><td>13</td></tr><tr><td><strong>06</strong></td><td><a href="/websec-decompiled/business-logic/">Business Logic</a></td><td>What happens when you skip steps in a checkout flow, enter negative quantities, or abuse coupon rules?</td><td>12</td></tr><tr><td><strong>07</strong></td><td><a href="/websec-decompiled/oauth/">OAuth Authentication</a></td><td>When you click &quot;Log in with social media,&quot; how can the return address (<code>redirect_uri</code>) be hijacked?</td><td>6</td></tr><tr><td><strong>08</strong></td><td><a href="/websec-decompiled/jwt/">JWT Attacks</a></td><td>When your login wristband is a JSON Web Token, what happens if the server forgets to verify its cryptographic seal?</td><td>8</td></tr></tbody></table><h3 id="🗄️-stage-3-·-databases-backend-systems" tabindex="-1">🗄️ Stage 3 · Databases &amp; Backend Systems <a class="header-anchor" href="#🗄️-stage-3-·-databases-backend-systems" aria-label="Permalink to &quot;🗄️ Stage 3 · Databases &amp; Backend Systems&quot;">​</a></h3><p><em>Follow user input as it travels behind the scenes into SQL databases, NoSQL stores, operating system shells, XML readers, and internal networks.</em></p><table tabindex="0"><thead><tr><th>Step</th><th>Case File</th><th>The Investigation Question</th><th>Labs</th></tr></thead><tbody><tr><td><strong>09</strong></td><td><a href="/websec-decompiled/sql-injection/">SQLi 00 · Mental Model</a></td><td>Why does a single quote (<code>&#39;</code>) trick a database into treating your search word as an official command?</td><td>2</td></tr><tr><td><strong>10</strong></td><td><a href="/websec-decompiled/sql-injection/01-union-attacks.html">SQLi 01 · UNION Attacks</a></td><td>How do you staple a second query onto the page&#39;s results to read secret tables?</td><td>4</td></tr><tr><td><strong>11</strong></td><td><a href="/websec-decompiled/sql-injection/02-db-fingerprinting.html">SQLi 02 · Fingerprinting</a></td><td>How do you ask the database which engine it runs and where it keeps its master directory of tables?</td><td>4</td></tr><tr><td><strong>12</strong></td><td><a href="/websec-decompiled/sql-injection/03-blind-sqli.html">SQLi 03 · Blind SQLi</a></td><td>How do you play &quot;20 Questions&quot; with a database when the webpage never shows any database rows?</td><td>7</td></tr><tr><td><strong>13</strong></td><td><a href="/websec-decompiled/sql-injection/04-waf-bypass-xml.html">SQLi 04 · WAF &amp; XML</a></td><td>Why does a security firewall see harmless encoded text while the database inside sees SQL commands?</td><td>1</td></tr><tr><td><strong>14</strong></td><td><a href="/websec-decompiled/nosql-injection/">NoSQL Injection</a></td><td>How do special JSON operators like <code>$ne</code> and <code>$regex</code> bypass login checks in modern document databases?</td><td>4</td></tr><tr><td><strong>15</strong></td><td><a href="/websec-decompiled/command-injection/">OS Command Injection</a></td><td>What happens when a web app pastes your input into a system terminal command?</td><td>5</td></tr><tr><td><strong>16</strong></td><td><a href="/websec-decompiled/ssrf/">Server-Side Request Forgery (SSRF)</a></td><td>How can you trick the public web server into fetching secret pages from its own private internal network?</td><td>7</td></tr><tr><td><strong>17</strong></td><td><a href="/websec-decompiled/xxe/">XXE Injection</a></td><td>How can an uploaded XML data file trick the server into reading local files off its hard drive?</td><td>9</td></tr></tbody></table><h3 id="🌐-stage-4-·-breaking-the-browser" tabindex="-1">🌐 Stage 4 · Breaking the Browser <a class="header-anchor" href="#🌐-stage-4-·-breaking-the-browser" aria-label="Permalink to &quot;🌐 Stage 4 · Breaking the Browser&quot;">​</a></h3><p><em>Shift your focus from the server to the user&#39;s browser. See how untrusted data turns into running scripts, forged clicks, and cross-site leaks.</em></p><table tabindex="0"><thead><tr><th>Step</th><th>Case File</th><th>The Investigation Question</th><th>Labs</th></tr></thead><tbody><tr><td><strong>18</strong></td><td><a href="/websec-decompiled/xss/">Cross-Site Scripting (XSS)</a></td><td>How does untrusted text end up running as live JavaScript inside another user&#39;s browser?</td><td>30</td></tr><tr><td><strong>19</strong></td><td><a href="/websec-decompiled/csrf/">CSRF</a></td><td>How can an outside website trick your browser into submitting account changes using your active login cookie?</td><td>11</td></tr><tr><td><strong>20</strong></td><td><a href="/websec-decompiled/dom/">DOM-Based Vulnerabilities</a></td><td>What happens when client-side JavaScript reads untrusted data from the URL and feeds it into a dangerous browser function?</td><td>7</td></tr><tr><td><strong>21</strong></td><td><a href="/websec-decompiled/clickjacking/">Clickjacking</a></td><td>How can a transparent invisible frame trick a user into clicking buttons on a site they didn&#39;t know was there?</td><td>5</td></tr><tr><td><strong>22</strong></td><td><a href="/websec-decompiled/cors/">CORS</a></td><td>When does a website accidentally give untrusted external domains permission to read private user responses?</td><td>3</td></tr><tr><td><strong>23</strong></td><td><a href="/websec-decompiled/websockets/">WebSockets</a></td><td>How do live two-way browser chat pipes fail when their initial connection or messages aren&#39;t verified?</td><td>2</td></tr></tbody></table><h3 id="⚡-stage-5-·-files-apis-modern-stacks" tabindex="-1">⚡ Stage 5 · Files, APIs &amp; Modern Stacks <a class="header-anchor" href="#⚡-stage-5-·-files-apis-modern-stacks" aria-label="Permalink to &quot;⚡ Stage 5 · Files, APIs &amp; Modern Stacks&quot;">​</a></h3><p><em>Investigate modern application features: file upload handlers, hidden API fields, GraphQL schemas, split-second race windows, and AI assistants.</em></p><table tabindex="0"><thead><tr><th>Step</th><th>Case File</th><th>The Investigation Question</th><th>Labs</th></tr></thead><tbody><tr><td><strong>24</strong></td><td><a href="/websec-decompiled/file-upload/">File Upload</a></td><td>When an app lets you upload an avatar image, what stops someone from uploading a script that the server executes?</td><td>7</td></tr><tr><td><strong>25</strong></td><td><a href="/websec-decompiled/api-testing/">API Testing</a></td><td>How do hidden API endpoints and auto-bound JSON fields (<code>isAdmin: true</code>) expose backend data?</td><td>5</td></tr><tr><td><strong>26</strong></td><td><a href="/websec-decompiled/graphql/">GraphQL</a></td><td>How do you ask a GraphQL endpoint for its own blueprint and spot missing permission checks on fields?</td><td>5</td></tr><tr><td><strong>27</strong></td><td><a href="/websec-decompiled/race-conditions/">Race Conditions</a></td><td>What happens when you send 20 requests at the exact same millisecond before the database finishes updating?</td><td>6</td></tr><tr><td><strong>28</strong></td><td><a href="/websec-decompiled/llm/">Web LLM Attacks</a></td><td>When an AI assistant is connected to internal company tools, how can untrusted text hijack its instructions?</td><td>8</td></tr></tbody></table><h3 id="🧠-stage-6-·-deep-protocol-engine-internals" tabindex="-1">🧠 Stage 6 · Deep Protocol &amp; Engine Internals <a class="header-anchor" href="#🧠-stage-6-·-deep-protocol-engine-internals" aria-label="Permalink to &quot;🧠 Stage 6 · Deep Protocol &amp; Engine Internals&quot;">​</a></h3><p><em>The masterclass stage. Dive beneath application code into reverse proxies, shared web caches, object deserializers, and language prototypes.</em></p><table tabindex="0"><thead><tr><th>Step</th><th>Case File</th><th>The Investigation Question</th><th>Labs</th></tr></thead><tbody><tr><td><strong>29</strong></td><td><a href="/websec-decompiled/request-smuggling/">HTTP Request Smuggling</a></td><td>What happens when the front-end proxy and back-end server disagree on where one HTTP request ends and the next begins?</td><td>22</td></tr><tr><td><strong>30</strong></td><td><a href="/websec-decompiled/cache-poisoning/">Web Cache Poisoning</a></td><td>How can you trick a shared web cache into saving a tampered page and serving it to every future visitor?</td><td>13</td></tr><tr><td><strong>31</strong></td><td><a href="/websec-decompiled/cache-deception/">Web Cache Deception</a></td><td>How can adding <code>.css</code> to a private account URL trick a public CDN into caching someone&#39;s personal profile?</td><td>5</td></tr><tr><td><strong>32</strong></td><td><a href="/websec-decompiled/deserialization/">Insecure Deserialization</a></td><td>Why is unpacking untrusted saved objects so dangerous, and how do existing code methods chain together?</td><td>10</td></tr><tr><td><strong>33</strong></td><td><a href="/websec-decompiled/prototype-pollution/">Prototype Pollution</a></td><td>How does modifying <code>__proto__</code> in JavaScript quietly plant properties onto every object in the entire app?</td><td>10</td></tr><tr><td><strong>34</strong></td><td><a href="/websec-decompiled/ssti/">Server-Side Template Injection</a></td><td>What happens when user input is pasted directly into an HTML template formula instead of passed as a variable?</td><td>7</td></tr><tr><td><strong>35</strong></td><td><a href="/websec-decompiled/host-header/">HTTP Host Header Attacks</a></td><td>Why is trusting the <code>Host:</code> header in an HTTP request dangerous for password-reset links and internal routing?</td><td>7</td></tr></tbody></table><hr><h2 id="how-every-case-file-is-built-for-easy-reading" tabindex="-1">How Every Case File Is Built for Easy Reading <a class="header-anchor" href="#how-every-case-file-is-built-for-easy-reading" aria-label="Permalink to &quot;How Every Case File Is Built for Easy Reading&quot;">​</a></h2><div class="wd-case"><div class="wd-step wd-step--see"><span class="wd-step__tag">🔎 Step 1 · What You Notice in the Browser</span><p>Every section starts with a real-world scene you can immediately picture—clicking a store category, resetting a password, or uploading a profile picture.</p></div><div class="wd-step wd-step--server"><span class="wd-step__tag">⚙️ Step 2 · What the Server Does Behind the Scenes</span><p>We open the curtain and trace how the server handles your request using visual flowcharts and color-coded highlights that separate <strong>Developer Code</strong> from <strong>Your Input</strong>.</p></div><div class="wd-step wd-step--break"><span class="wd-step__tag">💥 Step 3 · Where the Logic Breaks</span><p>Side-by-side cards compare <em>What the Developer Expected</em> vs. <em>What Actually Happened</em> so the root cause clicks immediately without academic jargon.</p></div><div class="wd-step wd-step--fix"><span class="wd-step__tag">🛡️ Step 4 · How to Lock It Down</span><p>Before jumping into the practice labs, you&#39;ll see the exact defensive fix developers use to close the gap permanently.</p></div></div><div class="wd-callout wd-callout--warn"><p><strong>Safe &amp; Authorized Practice Only.</strong> Every walkthrough and concept in this portal is designed for the deliberately vulnerable PortSwigger Web Security Academy labs and for building more secure software. Always test only on systems where you have explicit permission.</p></div>',24))])}const y=o(c,[["render",h]]);export{f as __pageData,y as default};
